#!/usr/bin/env python3
import sqlite3
import time

DB_PATH = "/var/lib/job-queue/jobs.sqlite3"


def open_db():
    connection = sqlite3.connect(DB_PATH, timeout=30)
    connection.row_factory = sqlite3.Row
    connection.execute("PRAGMA busy_timeout=30000")
    connection.execute("PRAGMA synchronous=FULL")
    return connection


def process_one(connection):
    connection.execute("BEGIN IMMEDIATE")
    try:
        row = connection.execute(
            "SELECT id, payload FROM jobs WHERE status = 'queued' ORDER BY rowid LIMIT 1"
        ).fetchone()
        if row is None:
            connection.rollback()
            return False

        connection.execute(
            "UPDATE jobs SET status = 'completed', result = ?, attempts = 1 "
            "WHERE id = ? AND status = 'queued'",
            ("processed:" + row["payload"], row["id"]),
        )
        connection.commit()
        return True
    except Exception:
        connection.rollback()
        raise


if __name__ == "__main__":
    connection = open_db()
    try:
        while True:
            if not process_one(connection):
                time.sleep(0.2)
    finally:
        connection.close()

